Below is a minimal Qt5 (Widgets) example that:

1. Prompts the user to pick a directory
2. Finds all `*.xls` / `*.xlsx` files in that directory
3. Creates a new subfolder (e.g. `csv_output`) inside that directory
4. Uses **Microsoft Excel via COM automation (ActiveQt / QAxObject)** to export each worksheet to a CSV file in that folder

**Notes / constraints**
- This approach is **Windows-only** and requires **Microsoft Excel installed**.
- Qt must be built/used with **ActiveQt** available (`QT += axcontainer`).

---

## `ExcelToCsv.pro`
```pro
QT       += widgets axcontainer
CONFIG   += c++11
TEMPLATE = app
TARGET   = ExcelToCsv

SOURCES  += main.cpp
```

---

## `main.cpp`
```cpp
#include <QApplication>
#include <QPushButton>
#include <QVBoxLayout>
#include <QTextEdit>
#include <QFileDialog>
#include <QDir>
#include <QFileInfo>
#include <QDateTime>
#include <QAxObject>

static QString sanitizeFileComponent(QString s)
{
    // Replace characters that are invalid in Windows filenames
    static const QChar repl = '_';
    const QString invalid = "\\/:*?\"<>|";
    for (QChar c : invalid) s.replace(c, repl);
    s = s.trimmed();
    if (s.isEmpty()) s = "Sheet";
    return s;
}

// Converts one Excel file to CSV(s), one per worksheet.
static bool convertExcelFileToCsvs(const QString& excelFilePath,
                                   const QString& outputDir,
                                   QString* errorOut = nullptr)
{
    // Start Excel
    QAxObject excelApp("Excel.Application");
    if (excelApp.isNull()) {
        if (errorOut) *errorOut = "Failed to create Excel.Application (is Excel installed?).";
        return false;
    }

    excelApp.setProperty("Visible", false);
    excelApp.setProperty("DisplayAlerts", false);

    QAxObject *workbooks = excelApp.querySubObject("Workbooks");
    if (!workbooks) {
        if (errorOut) *errorOut = "Failed to access Excel Workbooks.";
        excelApp.dynamicCall("Quit()");
        return false;
    }

    // Open workbook read-only (some installs accept this signature)
    QAxObject *workbook = workbooks->querySubObject("Open(const QString&)", excelFilePath);
    if (!workbook) {
        if (errorOut) *errorOut = "Failed to open workbook: " + excelFilePath;
        excelApp.dynamicCall("Quit()");
        return false;
    }

    QAxObject *worksheets = workbook->querySubObject("Worksheets");
    if (!worksheets) {
        if (errorOut) *errorOut = "Failed to access Worksheets.";
        workbook->dynamicCall("Close(Boolean)", false);
        excelApp.dynamicCall("Quit()");
        return false;
    }

    const int sheetCount = worksheets->property("Count").toInt();
    const QString baseName = QFileInfo(excelFilePath).completeBaseName();

    // Excel CSV file format constant: xlCSV = 6
    const int xlCSV = 6;

    for (int i = 1; i <= sheetCount; ++i) {
        QAxObject *sheet = worksheets->querySubObject("Item(int)", i);
        if (!sheet) continue;

        const QString sheetName = sanitizeFileComponent(sheet->property("Name").toString());
        const QString outPath = QDir(outputDir).filePath(baseName + "_" + sheetName + ".csv");

        // Worksheet::SaveAs exports the active sheet to CSV
        // Use native separators for COM
        const QString nativeOutPath = QDir::toNativeSeparators(outPath);
        QVariant result = sheet->dynamicCall("SaveAs(const QString&, int)", nativeOutPath, xlCSV);

        Q_UNUSED(result);
    }

    workbook->dynamicCall("Close(Boolean)", false);
    excelApp.dynamicCall("Quit()");
    return true;
}

int main(int argc, char *argv[])
{
    QApplication app(argc, argv);

    QWidget w;
    w.setWindowTitle("Excel -> CSV Converter (Qt5 + ActiveQt)");

    auto *btn = new QPushButton("Select Directory and Convert");
    auto *log = new QTextEdit;
    log->setReadOnly(true);

    auto *layout = new QVBoxLayout;
    layout->addWidget(btn);
    layout->addWidget(log);
    w.setLayout(layout);

    QObject::connect(btn, &QPushButton::clicked, [&]() {
        const QString dirPath = QFileDialog::getExistingDirectory(
            &w, "Select directory containing Excel files");

        if (dirPath.isEmpty())
            return;

        QDir dir(dirPath);

        // Output folder inside chosen directory
        const QString outFolderName = "csv_output";
        const QString outDirPath = dir.filePath(outFolderName);
        if (!dir.exists(outFolderName)) {
            if (!dir.mkdir(outFolderName)) {
                log->append("ERROR: Could not create output directory: " + outDirPath);
                return;
            }
        }

        log->append("Selected directory: " + dirPath);
        log->append("Output directory:   " + outDirPath);
        log->append("");

        QStringList filters;
        filters << "*.xls" << "*.xlsx";
        const QFileInfoList files = dir.entryInfoList(filters, QDir::Files | QDir::NoSymLinks);

        if (files.isEmpty()) {
            log->append("No .xls/.xlsx files found.");
            return;
        }

        int okCount = 0;
        int failCount = 0;

        for (const QFileInfo& fi : files) {
            const QString inPath = fi.absoluteFilePath();
            log->append("Converting: " + fi.fileName());

            QString err;
            if (convertExcelFileToCsvs(inPath, outDirPath, &err)) {
                okCount++;
                log->append("  OK");
            } else {
                failCount++;
                log->append("  FAILED: " + err);
            }
            log->append("");
        }

        log->append(QString("Done. Success: %1  Failed: %2").arg(okCount).arg(failCount));
    });

    w.resize(700, 450);
    w.show();

    return app.exec();
}
```

---

### Build / run
- Open the `.pro` in Qt Creator (Qt 5 on Windows), configure a kit that includes ActiveQt, build, run.

---

If you want this to work **cross-platform** (macOS/Linux) *without* Excel installed, tell me which Excel formats you care about (`.xlsx` only vs `.xls` too), and I’ll provide an alternative using an open-source parser/writer instead of COM automation.

